<?php defined( 'ABSPATH' ) || exit; $data = prntlab_demo_data(); ?>
<section class="reviews-section" aria-labelledby="reviews-title"><div class="section-heading"><h2 id="reviews-title"><?php echo esc_html( prntlab_home( 'reviews_title' ) ); ?></h2></div><div class="reviews-grid">
<?php foreach ( $data['reviews'] as $i => $item ) : $n = $i + 1; $avatar = prntlab_image_url( prntlab_field( 'review_' . $n . '_avatar' ) ); ?>
  <figure class="review-card"><div class="review-avatar"><?php if ( $avatar ) : ?><img src="<?php echo esc_url( $avatar ); ?>" width="52" height="52" loading="lazy" alt=""><?php else : ?><span><?php echo esc_html( $item['initial'] ); ?></span><?php endif; ?></div><div><figcaption><?php echo esc_html( prntlab_field( 'review_' . $n . '_name', $item['name'] ) ); ?></figcaption><p class="review-stars" aria-label="<?php esc_attr_e( '5 из 5', 'prntlab' ); ?>">★★★★★</p><blockquote><?php echo esc_html( prntlab_field( 'review_' . $n . '_text', $item['text'] ) ); ?></blockquote><p class="review-date"><?php echo esc_html( prntlab_field( 'review_' . $n . '_date', $item['date'] ) ); ?></p></div></figure>
<?php endforeach; ?></div><p class="demo-disclaimer"><?php echo esc_html( prntlab_home( 'reviews_note' ) ); ?></p></section>
